1	export type QuoteResult = { premium: number };
2	
3	export type ScenarioResults = { results: QuoteResult[] };
4	
5	const PROCESSING_FEE = 5;
6	
7	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
8	
9	const ITEM_BASE_PREMIUM: Record<string, number> = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	};
17	
18	type Item = { type: string; cursed?: boolean; enchantment?: number };
19	
20	type Step = { op: string; items: Item[] };
21	
22	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
23	
24	const BLOCK_SIZE = 3;
25	
26	// A block is exactly BLOCK_SIZE components of the same type, priced as a unit.
27	// Exactly: 4 runes are not a block (4 x 25), and 2 runes + 1 moonstone is not
28	// a block either — "alike" means the same type, not the same family.
29	const BLOCK_BASE_PREMIUM = 60;
30	
31	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
32	
33	const countByType = (items: Item[]): Map<string, number> =>
34	  items.reduce(
35	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
36	    new Map<string, number>(),
37	  );
38	
39	const isBlock = (type: string, count: number): boolean =>
40	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
41	
42	const groupBasePremium = (type: string, count: number): number =>
43	  isBlock(type, count) ? BLOCK_BASE_PREMIUM : count * ITEM_BASE_PREMIUM[type];
44	
45	const sum = (numbers: number[]): number =>
46	  numbers.reduce((total, value) => total + value, 0);
47	
48	const policyBasePremium = (items: Item[]): number =>
49	  sum(
50	    [...countByType(items)].map(([type, count]) =>
51	      groupBasePremium(type, count),
52	    ),
53	  );
54	
55	const CURSE_SURCHARGE_RATE = 0.5;
56	
57	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
58	
59	const HIGH_ENCHANTMENT_THRESHOLD = 5;
60	
61	const isCursed = (item: Item): boolean => item.cursed === true;
62	
63	const isHighlyEnchanted = (item: Item): boolean =>
64	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
65	
66	// Both surcharges can apply to the same item, so the rates add.
67	const itemSurchargeRate = (item: Item): number =>
68	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
69	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
70	
71	// Item-specific modifiers apply to the affected item's own base premium, not to
72	// the policy total — note that is the *ungrouped* base premium, so a cursed
73	// rune inside a block is surcharged on 25 G, not on a share of the block's 60.
74	const itemModifierSurcharges = (items: Item[]): number =>
75	  sum(items.map((item) => ITEM_BASE_PREMIUM[item.type] * itemSurchargeRate(item)));
76	
77	const quoteStep = (step: Step): QuoteResult => {
78	  // Item-specific surcharges land here, before any policy-wide percentage
79	  // modifier — those are levied on the base premium including them.
80	  const baseAfterItemModifiers =
81	    policyBasePremium(step.items) + itemModifierSurcharges(step.items);
82	  // Deliberately additive, not `base * (1 + rate)`: the latter is the same in
83	  // exact arithmetic but not in binary floating point (100 * 1.1 is
84	  // 110.00000000000001), and Math.ceil turns that 1e-14 into a whole gold piece.
85	  const afterPercentageModifiers =
86	    baseAfterItemModifiers +
87	    baseAfterItemModifiers * FIRST_INSURANCE_SURCHARGE_RATE;
88	
89	  // The fee is added after every percentage modifier, and only the final
90	  // premium is rounded — intermediates stay fractional.
91	  return { premium: Math.ceil(afterPercentageModifiers + PROCESSING_FEE) };
92	};
93	
94	export const runScenario = (scenario: Scenario): ScenarioResults => ({
95	  results: scenario.steps.map(quoteStep),
96	});
97

